    expect(parseStatusArgs(["--db=x.db", "--budget=0"])).toEqual({ db: "x.db", budgetUsd: 0 });
  });

  test("rejects a flag without a value", () => {
    expect(() => parseStatusArgs(["--db"])).toThrow("--db needs a value");
  });
});

